<script lang="ts">
 import {onMount,onDestroy} from 'svelte';
 import {Button} from '@hasbai/ui/button';
 import {Input} from '@hasbai/ui/input';
 import {Notice} from '@hasbai/ui/notice';
 import * as Dialog from '@hasbai/ui/dialog';
 import {Image,Upload,Sparkles,Search,Copy,Pencil,Sun,Moon,LogOut,ArrowUpRight} from '@lucide/svelte';
 import {maxImageBytes,imageModels,type ImageModel,type ImageAsset} from '@hasbai/images';
 import type {Api} from '../lib';
 let {api,logout}:{api:Api;logout:()=>void}=$props();
 let model=$state<ImageModel>('gpt-image-2.5-flare');
 let images=$state<ImageAsset[]>([]),admin=$state(false),scope=$state('mine'),query=$state(''),page=$state(1),hasMore=$state(false),loading=$state(true),busy=$state(false),generating=$state(false),error=$state(''),status=$state(''),prompt=$state(''),dark=$state(false);
 let recent=$state<ImageAsset>();
 let selected=$state<ImageAsset>(),name=$state(''),renaming=$state(false),renameError=$state('');let fileInput:HTMLInputElement;let controller:AbortController|undefined;let loadId=0;
 onMount(()=>{dark=document.documentElement.classList.contains('dark');void init();});onDestroy(()=>controller?.abort());
 async function init(){try{admin=(await api.me()).admin;scope=admin?'all':'mine';await load();}catch(e){error=(e as Error).message;loading=false;}}
 async function load(reset=false){if(reset)page=1;const id=++loadId;loading=true;error='';try{const result=await api.list(query,page,scope);if(id!==loadId)return;images=result.images;hasMore=result.hasMore;}catch(e){if(id===loadId)error=(e as Error).message;}finally{if(id===loadId)loading=false;}}
 async function upload(event:Event){const input=event.currentTarget as HTMLInputElement,file=input.files?.[0];if(!file||busy)return;busy=true;error='';status='';try{if(file.size>maxImageBytes)throw Error('图片不能超过 10 MB');recent=await api.upload(file);status='已上传';await load(true);}catch(e){error=(e as Error).message;}finally{input.value='';busy=false;}}
 async function generate(event:SubmitEvent){event.preventDefault();if(generating||!prompt.trim())return;error='';status='';generating=true;const active=new AbortController();controller=active;try{const result=await api.generate(prompt,model,active.signal);if(!active.signal.aborted){recent=result;status='已生成并保存';await load(true);}}catch(e){if(!active.signal.aborted)error=(e as Error).message;}finally{generating=false;}}
 async function copy(image:ImageAsset){try{await navigator.clipboard.writeText(image.url);status='已复制图片链接';}catch{error='复制失败，请打开图片后复制地址';}}
 function edit(image:ImageAsset){selected=image;name=image.name;renameError='';}
 async function rename(event:SubmitEvent){event.preventDefault();if(!selected||renaming)return;renaming=true;renameError='';try{await api.rename(selected.id,name);selected=undefined;status='已重命名';await load();}catch(e){renameError=(e as Error).message;}finally{renaming=false;}}
 function theme(){dark=!dark;document.documentElement.classList.toggle('dark',dark);}
</script>
<svelte:head><title>图床 · 北极小站</title></svelte:head>
<header class="app-header"><a class="brand" href="/"><Image size={22} aria-hidden="true"/><span>图床</span></a><nav aria-label="应用"><a href="https://hasbai.xyz">博客<ArrowUpRight size={14} aria-hidden="true"/></a><a href="https://tavern.hasbai.xyz">酒馆<ArrowUpRight size={14} aria-hidden="true"/></a><Button variant="ghost" aria-label={dark?'切换浅色模式':'切换深色模式'} onclick={theme}>{#if dark}<Sun size={18}/>{:else}<Moon size={18}/>{/if}</Button><Button variant="ghost" aria-label="退出登录" onclick={logout}><LogOut size={18}/></Button></nav></header>
<main class="workspace"><header class="page-head"><h1>图片库</h1><Button disabled={busy} onclick={()=>fileInput.click()}><Upload size={17} aria-hidden="true"/>{busy?'上传中…':'上传图片'}</Button></header>
<input class="sr-only" type="file" bind:this={fileInput} accept="image/png,image/jpeg,image/webp,image/gif" aria-label="上传图片文件" onchange={upload}/>
<form class="generation" onsubmit={generate}><div class="generation-heading"><Sparkles size={18} aria-hidden="true"/><h2>AI 生成</h2><label class="model-choice"><span class="sr-only">生成模型</span><select bind:value={model} disabled={generating}>{#each imageModels as option}<option value={option.id}>{option.label}</option>{/each}</select></label></div><label class="sr-only" for="prompt">图片描述</label><textarea id="prompt" bind:value={prompt} maxlength="1800" rows="3" disabled={generating} placeholder="描述画面、人物和风格"></textarea><div class="generation-actions">{#if generating}<span role="status">正在生成图片…</span><Button type="button" variant="outline" onclick={()=>{controller?.abort();status='已取消生成';}}>取消生成</Button>{:else}<Button type="submit" disabled={!prompt.trim()}><Sparkles size={16} aria-hidden="true"/>生成图片</Button>{/if}</div></form>
<div class="toolbar"><form class="search" onsubmit={event=>{event.preventDefault();void load(true);}}><label class="sr-only" for="search">搜索图片</label><Input id="search" bind:value={query} placeholder="搜索图片名称"/><Button variant="outline" aria-label="搜索图片" type="submit"><Search size={18}/></Button></form>{#if admin}<label class="scope"><span class="sr-only">图片范围</span><select bind:value={scope} onchange={()=>load(true)}><option value="all">全部图片</option><option value="mine">我的图片</option></select></label>{/if}</div>
{#if error}<Notice variant="error">{error}<Button variant="outline" onclick={()=>load()}>重试</Button></Notice>{/if}{#if status}<p class="feedback" role="status">{status}</p>{/if}
{#if recent}<div class="recent"><a href={recent.url} target="_blank" rel="noopener noreferrer"><img src={recent.url} alt={recent.name} width="56" height="56"/></a><div><strong>{recent.name}</strong><span>已保存到图床</span></div><Button variant="outline" onclick={()=>copy(recent!)}><Copy size={16} aria-hidden="true"/>复制链接</Button></div>{/if}
{#if loading}<div class="empty" role="status">正在加载图片…</div>{:else if !error&&!images.length}<div class="empty"><Image size={36} aria-hidden="true"/><h2>{query?'没有匹配的图片':'还没有图片'}</h2><p>{query?'试试其他名称':'上传图片，或描述你想生成的画面。'}</p></div>{:else if !error}<div class="image-grid">{#each images as image(image.id)}<article class="image-card"><a class="image-preview" href={image.url} target="_blank" rel="noopener noreferrer"><img src={image.url} alt={image.name} loading="lazy" width="320" height="240"/></a><div class="image-info"><h2 title={image.name}>{image.name}</h2><p>{(image.size/1024).toFixed(0)} KB · {image.content_type.replace('image/','').toUpperCase()}{#if image.model} · {image.model.endsWith('sunburst')?'Sunburst':'Flare'}{/if}</p><div class="image-actions"><Button variant="ghost" aria-label={`复制 ${image.name} 链接`} onclick={()=>copy(image)}><Copy size={16} aria-hidden="true"/>复制链接</Button><Button variant="ghost" aria-label={`重命名 ${image.name}`} onclick={()=>edit(image)}><Pencil size={16}/></Button></div></div></article>{/each}</div><div class="pagination"><Button variant="outline" disabled={page===1} onclick={()=>{page--;void load();}}>上一页</Button><span>第 {page} 页</span><Button variant="outline" disabled={!hasMore} onclick={()=>{page++;void load();}}>下一页</Button></div>{/if}
</main>
<Dialog.Root open={!!selected} onOpenChange={open=>{if(!open&&!renaming)selected=undefined;}}><Dialog.Content><Dialog.Header><Dialog.Title>重命名图片</Dialog.Title></Dialog.Header><form class="rename" onsubmit={rename}><label for="name">图片名称</label><Input id="name" bind:value={name} maxlength={240}/>{#if renameError}<Notice variant="error">{renameError}</Notice>{/if}<Dialog.Footer><Button type="button" variant="outline" disabled={renaming} onclick={()=>selected=undefined}>取消</Button><Button type="submit" disabled={renaming||!name.trim()}>{renaming?'保存中…':'保存'}</Button></Dialog.Footer></form></Dialog.Content></Dialog.Root>
